const envelope=$input.first().json;
const expected=String((typeof $env!=='undefined'?$env.SIMULATOR_WEBHOOK_TOKEN:'')||'').trim();
const auth=String(envelope.headers?.authorization||'');
const received=String(envelope.headers?.['x-smart-classroom-token']||(auth.startsWith('Bearer ')?auth.slice(7):'')).trim();
if(expected&&received!==expected)throw new Error('SIMULATOR_WEBHOOK_UNAUTHORIZED');
const input = envelope;
const body = input.body ?? input;
const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!isObject(body)) throw new Error('ACK phải là JSON object.');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof body.command_id !== 'string' || !uuid.test(body.command_id)) throw new Error('command_id phải là UUID hợp lệ.');
if (typeof body.device_id !== 'string' || !body.device_id.trim()) throw new Error('Thiếu device_id.');
if (!['SUCCESS', 'FAILED'].includes(body.status)) throw new Error('status phải là SUCCESS hoặc FAILED.');
if (body.status === 'SUCCESS' && !isObject(body.actual_state)) throw new Error('ACK SUCCESS phải có actual_state.');
for (const key of ['actual_state', 'actual_levels', 'simulated_state']) {
  if (body[key] !== undefined && !isObject(body[key])) throw new Error(key + ' phải là object.');
}
if (body.sequence !== undefined && (!Number.isSafeInteger(body.sequence) || body.sequence < 0)) throw new Error('sequence phải là số nguyên không âm.');
if (body.message !== undefined && (typeof body.message !== 'string' || body.message.length > 1000)) throw new Error('message phải là chuỗi tối đa 1000 ký tự.');
const fields = ['command_id', 'device_id', 'device_code', 'status', 'actual_state', 'actual_levels', 'simulated_state', 'message', 'sequence'];
const ack_payload = Object.fromEntries(fields.filter(k => body[k] !== undefined).map(k => [k, body[k]]));
return [{json: {
  ack_payload,
  received_at: new Date().toISOString()
}}];

const response = $input.first().json;
const source = $('Validate ACK Payload').first().json;
const ack = source.ack_payload;
const base = {
  workflow_version: 'V3',
  command_id: ack.command_id,
  device_id: ack.device_id,
  ack_status: ack.status,
  received_at: source.received_at
};
function failure(code, type, message) {
  return [{json: {...base, success: false, ok: false, http_status: code, error_type: type, error: message, ack_confirmed: false}}];
}
if (response.error || !Number.isInteger(response.statusCode)) {
  return failure(503, 'BACKEND_UNAVAILABLE', 'Không nhận được phản hồi hợp lệ từ backend. ACK chưa được xác nhận đã lưu.');
}
const statusCode = response.statusCode;
let result = response.body;
if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch { result = null; }
}
if (statusCode < 200 || statusCode >= 300) {
  const message = Array.isArray(result?.message) ? result.message.join(' | ') : typeof result?.message === 'string' ? result.message : 'Backend từ chối ACK.';
  const code = statusCode >= 400 && statusCode <= 599 ? statusCode : 502;
  return failure(code, 'BACKEND_REJECTED', message);
}
if (!result || result.ok !== true) return failure(502, 'INVALID_BACKEND_RESPONSE', 'Backend không xác nhận ok=true.');
if (result.command_id !== undefined && result.command_id !== ack.command_id) return failure(502, 'COMMAND_ID_MISMATCH', 'Backend trả sai command_id.');
const late = result.late === true;
const duplicate = result.duplicate === true;
if (!late && !['ACK', 'FAILED'].includes(result.status)) return failure(502, 'INVALID_BACKEND_RESPONSE', 'Backend trả trạng thái ACK không hợp lệ.');
if (!late && result.status !== (ack.status === 'SUCCESS' ? 'ACK' : 'FAILED')) return failure(502, 'ACK_STATUS_MISMATCH', 'Trạng thái backend không khớp ACK đã gửi.');
return [{json: {
  ...base,
  success: true,
  ok: true,
  http_status: 200,
  status: result.status ?? null,
  duplicate,
  late,
  applied: typeof result.applied === 'boolean' ? result.applied : null,
  ack_confirmed: !late && result.status === 'ACK',
  backend_result: result
}}];

const ack = $input.first().json;
const payload = $('Validate ACK Payload').first().json.ack_payload;
return [{json: {
  ...ack,
  incident_delivery: 'NOT_CONNECTED',
  incident_candidate: {
    type: 'COMMAND_FAILURE',
    severity: 'HIGH',
    title: 'Thiết bị báo thực hiện lệnh thất bại',
    source: 'WF05',
    event_key: 'WF05:FAILED:' + ack.command_id,
    dedup_key: 'cmd-failed-' + ack.command_id,
    device_id: ack.device_id,
    command_id: ack.command_id,
    observed_at: ack.received_at,
    recovered: false,
    details: {
      event_type: 'COMMAND_FAILED',
      command_id: ack.command_id,
      ack_status: ack.ack_status,
      message: payload.message ?? 'Device reported failure',
      actual_state: payload.actual_state ?? null,
      actual_levels: payload.actual_levels ?? null
    }
  },
  message: 'Backend đã lưu ACK FAILED. Đã chuẩn bị dữ liệu sự cố, chưa gửi flow 10.'
}}];

const ack = $input.first().json;
return [{json: {
  ...ack,
  ack_confirmed: false,
  incident_delivery: 'NOT_CONNECTED',
  incident_candidate: {
    type: 'COMMAND_FAILURE',
    severity: 'MEDIUM',
    title: 'ACK đến khi lệnh đã hết hạn hoặc bị hủy',
    source: 'WF05',
    event_key: 'WF05:LATE_ACK:' + ack.command_id,
    dedup_key: 'late-ack-' + ack.command_id,
    device_id: ack.device_id,
    command_id: ack.command_id,
    observed_at: ack.received_at,
    recovered: false,
    details: {
      event_type: 'LATE_ACK',
      command_id: ack.command_id,
      ack_status: ack.ack_status,
      late: true,
      applied: ack.applied
    }
  },
  message: 'Backend đã ghi nhận ACK muộn nhưng không áp dụng vào trạng thái xác nhận. Chưa gửi flow 10.'
}}];

const ack = $input.first().json;
return [{json: {
  ...ack,
  incident_candidate: null,
  message: ack.duplicate
    ? 'Backend đã có ACK này; không tạo thêm đề xuất sự cố.'
    : 'Backend đã lưu ACK thành công.',
  processed_at: new Date().toISOString()
}}];

const ack = $input.first().json;
return [{json: {
  ...ack,
  success: false,
  ok: false,
  ack_confirmed: false,
  message: 'ACK chưa được xác nhận đã lưu. Xem error và http_status.',
  processed_at: new Date().toISOString()
}}];

return $input.all().flatMap((item, index) => {
  const result = item.json;
  const candidate = result.incident_candidate;

  if (
    result.success !== true ||
    result.duplicate === true ||
    result.late === true ||
    result.status !== 'FAILED' ||
    !candidate ||
    typeof candidate !== 'object'
  ) {
    return [];
  }

  return [{
    json: candidate,
    pairedItem: { item: index }
  }];
});
